fast_pseudocode:
# Correct autotune pattern: grid must use meta['XBLOCK']
@triton.autotune(
    configs=[triton.Config({'XBLOCK': 512}, num_warps=4), ...],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    ...

# CRITICAL: grid must be a lambda consuming meta['XBLOCK']
grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](...)
